SELECT COUNT(*)
FROM registration a
WHERE a.company_id = #{companyId}
    AND a.del_flag = #{delFlag}
    AND a.is_pre IS NULL
    AND a.status != 'registrationStatus_4'
    AND a.create_date >= #{startDate}
    AND a.create_date < #{endDate}

SELECT COUNT(*)
FROM registration a
WHERE a.company_id = #{companyId}
    AND a.del_flag = #{delFlag}
    AND a.is_pre IS NULL
    AND a.status != 'registrationStatus_4'
    AND a.charge_status IN ('0', '1')
    AND a.create_date >= #{startDate}
    AND a.create_date < #{endDate}
